// NULL-tolerant scan buffer for gameServerDiagnosisScanMapperNullable:
// on a LEFT JOIN miss every column comes back NULL, so each field uses the
// nullable version of the column type even when the column itself is NOT NULL.
type gameServerDiagnosisPreloadBuf struct {
	GameServerID      null.Val[string]
	NodeID            null.Val[string]
	ExecutionID       null.Val[string]
	AttemptStartedAt  null.Val[int64]
	OccurredAt        null.Val[int64]
	Stage             null.Val[string]
	Category          null.Val[string]
	Error             null.Val[string]
	Evidence          null.Val[string]
	MatchedEvidence   null.Val[string]
	Truncated         null.Val[bool]
	EvidenceAvailable null.Val[bool]
	ExitCode          null.Val[int64]
	Quality           null.Val[int64]
}

// gameServerDiagnosisScanMapperNullable maps the preloaded gameServerDiagnosis
// columns (prefixed with the runtime join alias) without reflection, while
// keeping the LEFT JOIN semantics of the reflection-based mapper: a row whose
// prefixed columns are all NULL yields nil (no child), and NULL values never
// error, they just leave the zero value in the field.
func gameServerDiagnosisScanMapperNullable(prefix string) scan.Mapper[*GameServerDiagnosis] {
	return func(ctx context.Context, cols []string) (scan.BeforeFunc, func(any) (*GameServerDiagnosis, error)) {
		// resolve the column names once per query, not per row
		type target struct {
			idx int
			dst func(b *gameServerDiagnosisPreloadBuf) any
		}
		targets := make([]target, 0, 14)
		for i, col := range cols {
			name, ok := strings.CutPrefix(col, prefix)
			if !ok {
				continue
			}
			switch name {
			case "game_server_id":
				targets = append(targets, target{i, func(b *gameServerDiagnosisPreloadBuf) any { return &b.GameServerID }})
			case "node_id":
				targets = append(targets, target{i, func(b *gameServerDiagnosisPreloadBuf) any { return &b.NodeID }})
			case "execution_id":
				targets = append(targets, target{i, func(b *gameServerDiagnosisPreloadBuf) any { return &b.ExecutionID }})
			case "attempt_started_at":
				targets = append(targets, target{i, func(b *gameServerDiagnosisPreloadBuf) any { return &b.AttemptStartedAt }})
			case "occurred_at":
				targets = append(targets, target{i, func(b *gameServerDiagnosisPreloadBuf) any { return &b.OccurredAt }})
			case "stage":
				targets = append(targets, target{i, func(b *gameServerDiagnosisPreloadBuf) any { return &b.Stage }})
			case "category":
				targets = append(targets, target{i, func(b *gameServerDiagnosisPreloadBuf) any { return &b.Category }})
			case "error":
				targets = append(targets, target{i, func(b *gameServerDiagnosisPreloadBuf) any { return &b.Error }})
			case "evidence":
				targets = append(targets, target{i, func(b *gameServerDiagnosisPreloadBuf) any { return &b.Evidence }})
			case "matched_evidence":
				targets = append(targets, target{i, func(b *gameServerDiagnosisPreloadBuf) any { return &b.MatchedEvidence }})
			case "truncated":
				targets = append(targets, target{i, func(b *gameServerDiagnosisPreloadBuf) any { return &b.Truncated }})
			case "evidence_available":
				targets = append(targets, target{i, func(b *gameServerDiagnosisPreloadBuf) any { return &b.EvidenceAvailable }})
			case "exit_code":
				targets = append(targets, target{i, func(b *gameServerDiagnosisPreloadBuf) any { return &b.ExitCode }})
			case "quality":
				targets = append(targets, target{i, func(b *gameServerDiagnosisPreloadBuf) any { return &b.Quality }})
			}
		}

		// One scratch buffer reused for every row: before -> scan -> after runs
		// synchronously per row, the scheduled columns are fully overwritten each
		// row, and unselected columns stay zero, so a single buffer preserves the
		// per-row NULL semantics without allocating a buffer per parent row. The
		// returned child (o below) is always freshly allocated, so buf never
		// escapes past the after func.
		buf := new(gameServerDiagnosisPreloadBuf)
		return func(row *scan.Row) (any, error) {
				for _, t := range targets {
					row.ScheduleScanByIndex(t.idx, t.dst(buf))
				}
				return buf, nil
			}, func(link any) (*GameServerDiagnosis, error) {
				buf := link.(*gameServerDiagnosisPreloadBuf)

				// Same rule as the reflection mapper's row validator: the child
				// exists only if at least one of its columns is not NULL. Columns
				// not selected by the query are never scanned and stay invalid,
				// so this check also matches when only a subset is selected.
				if !(buf.GameServerID.IsValue()) &&
					!(buf.NodeID.IsValue()) &&
					!(buf.ExecutionID.IsValue()) &&
					!(buf.AttemptStartedAt.IsValue()) &&
					!(buf.OccurredAt.IsValue()) &&
					!(buf.Stage.IsValue()) &&
					!(buf.Category.IsValue()) &&
					!(buf.Error.IsValue()) &&
					!(buf.Evidence.IsValue()) &&
					!(buf.MatchedEvidence.IsValue()) &&
					!(buf.Truncated.IsValue()) &&
					!(buf.EvidenceAvailable.IsValue()) &&
					!(buf.ExitCode.IsValue()) &&
					!(buf.Quality.IsValue()) {
					return nil, nil
				}

				o := new(GameServerDiagnosis)
				if buf.GameServerID.IsValue() {
					o.GameServerID = buf.GameServerID.MustGet()
				}
				if buf.NodeID.IsValue() {
					o.NodeID = buf.NodeID.MustGet()
				}
				if buf.ExecutionID.IsValue() {
					o.ExecutionID = buf.ExecutionID.MustGet()
				}
				if buf.AttemptStartedAt.IsValue() {
					o.AttemptStartedAt = buf.AttemptStartedAt.MustGet()
				}
				if buf.OccurredAt.IsValue() {
					o.OccurredAt = buf.OccurredAt.MustGet()
				}
				if buf.Stage.IsValue() {
					o.Stage = buf.Stage.MustGet()
				}
				if buf.Category.IsValue() {
					o.Category = buf.Category.MustGet()
				}
				if buf.Error.IsValue() {
					o.Error = buf.Error.MustGet()
				}
				if buf.Evidence.IsValue() {
					o.Evidence = buf.Evidence.MustGet()
				}
				if buf.MatchedEvidence.IsValue() {
					o.MatchedEvidence = buf.MatchedEvidence.MustGet()
				}
				if buf.Truncated.IsValue() {
					o.Truncated = buf.Truncated.MustGet()
				}
				if buf.EvidenceAvailable.IsValue() {
					o.EvidenceAvailable = buf.EvidenceAvailable.MustGet()
				}
				o.ExitCode = buf.ExitCode
				if buf.Quality.IsValue() {
					o.Quality = buf.Quality.MustGet()
				}
				return o, nil
			}
	}
}

